import json

async def execute(self, inputs):
    from src.runtime.assets.assembly import get_scene_population_engine, EnvironmentPlan

    env_plan_json = str(inputs.get('environment_plan_json') or '')
    if not env_plan_json.strip():
        self.log_error('[ScenePopulation] environment_plan_json is required.')
        return {'population_plan_json': '{}', 'plan_id': '', 'total_assets': 0, 'balance_score': 0.0, 'hero_asset_count': 0, 'ok': False, 'exec_out': True}

    try:
        env_dict = json.loads(env_plan_json)
        env_plan = EnvironmentPlan.from_dict(env_dict)

        engine = get_scene_population_engine()
        plan   = engine.populate_scene(env_plan)

        hero_group = plan.groups.get('hero_assets')
        hero_count = hero_group.asset_count if hero_group else 0

        self.log_info(
            f'[ScenePopulation] {env_plan.environment!r}: '
            f'{plan.total_assets} assets, balance={plan.balance_score:.2f}, ok={plan.ok}'
        )
        if plan.warnings:
            for w in plan.warnings:
                self.log_warning(f'[ScenePopulation] {w}')

        return {
            'population_plan_json': json.dumps(plan.to_dict()),
            'plan_id':       plan.plan_id,
            'total_assets':  plan.total_assets,
            'balance_score': plan.balance_score,
            'hero_asset_count': hero_count,
            'ok':            plan.ok,
            'exec_out':      True,
        }
    except Exception as e:
        self.log_error(f'[ScenePopulation] {e}')
        return {'population_plan_json': '{}', 'plan_id': '', 'total_assets': 0, 'balance_score': 0.0, 'hero_asset_count': 0, 'ok': False, 'exec_out': True}

def register_node():
    from src.nodes.base import BaseNode
    class Hou_Mcp_Scene_Population(BaseNode):
        name = 'hou_mcp_scene_population'
        async def execute(self, inputs):
            return await execute(self, inputs)
    return Hou_Mcp_Scene_Population
